style.css:
@-moz-document domain("roblox.com") {
/* ==========================================================
   Blue Hour - Roblox theme for Stylish
   1. Variables      7. Search
   2. Background     8. Chat and Friends
   3. Transparent    9. Games / Badges
   4. Navigation    10. Inventory
   5. Typography    11. Profile / Transactions
   6. Controls      12. Messages
   ========================================================== */


/* ==========================================================
   1. VARIABLES
   ========================================================== */
:root {
  --bh-bg:       #0a1024;
  --bh-bg-2:     #0f1730;
  --bh-bg-3:     #060a18;
  --bh-surface:  #141d3a;
  --bh-raised:   #1b2650;
  --bh-border:   #263463;
  --bh-accent:   #7aa2ff;
  --bh-accent-2: #a99bff;
  --bh-text:     #e0e7fb;
  --bh-muted:    #aab6dc;
  --bh-green:    #9fe0b0;
  --bh-glow:     rgba(122, 162, 255, .25);
  --bh-gradient: linear-gradient(135deg, #4f78e6, #7b6cf0);
  --bh-icon-tint: brightness(0) invert(1) sepia(1) hue-rotate(185deg) saturate(3);

  --color-content-emphasis:        #e4eaff;
  --color-content-default:         #d6def5;
  --color-content-standard:        #d6def5;
  --color-content-muted:           #b4c0e6;
  --color-content-action-standard: #e0e7fb;
  --color-content-action-utility:  #e0e7fb;
}

:root, body {
  --color-surface-100: transparent !important;
  --color-surface-200: transparent !important;
  --color-surface-300: transparent !important;
}


/* ==========================================================
   2. BACKGROUND (dark ambient: vignette + soft colored glows)
   ========================================================== */
html, body, body.rbx-body, #wrap, .wrap {
  background-color: var(--bh-bg) !important;
  background-image:
    /* vignette: dark edges (raise .70 for darker) */
    radial-gradient(ellipse at 50% 40%, transparent 35%, rgba(2, 5, 15, .70) 100%),
    /* blue glow, top left */
    radial-gradient(900px 600px at 12% -5%, rgba(122, 162, 255, .20), transparent 65%),
    /* purple glow, right */
    radial-gradient(800px 600px at 100% 15%, rgba(169, 155, 255, .16), transparent 60%),
    /* blue glow, bottom */
    radial-gradient(1000px 500px at 50% 115%, rgba(79, 120, 230, .18), transparent 65%),
    /* base color */
    linear-gradient(180deg, #0a1024 0%, #070b1a 100%) !important;
  background-repeat: no-repeat !important;
  background-size: auto !important;
  background-attachment: fixed !important;
  color: var(--bh-text) !important;
}

::selection { background: var(--bh-accent); color: var(--bh-bg); }

::-webkit-scrollbar { width: 10px; height: 10px; }
::-webkit-scrollbar-track { background: var(--bh-bg); }
::-webkit-scrollbar-thumb { background: var(--bh-raised); border-radius: 8px; }
::-webkit-scrollbar-thumb:hover { background: var(--bh-accent); }


/* ==========================================================
   3. TRANSPARENT CONTAINERS
   ========================================================== */
.container-main, .content, #container-main, #content,
.section, .section-content, .section-content-off, .content-background,
.card, .list-item, .tab-content, .rbx-tab-content, .tab-content-group,
.profile-container, .profile-about-content, .profile-about-content-text,
.game-card-container, .game-card-link, .game-card-info,
.item-card-container,
.info-container, .info-metadata-container,
.wide-game-tile-metadata, .base-metadata, .hover-metadata,
.game-tile, .game-container, .game-carousel, .game-sort-carousel-wrapper,
.game-description, .stat-container,
.container-header, .container-list,
.home-container, #HomeContainer,
.friend-carousel-container, .friends-carousel-container,
[class*="home-"]:not([class*="icon"]), [class*="game-sort"], [class*="friend-"]:not([class*="icon"]),
.home-header, #place-list > div:first-child,
.content > div:first-child, #content > div:first-child,
h1, h1 * {
  background: transparent !important;
  background-color: transparent !important;
  box-shadow: none !important;
}

.game-card-container, .game-card-link, .item-card-container,
.section, .section-content, .card, .list-item, .profile-container {
  border-color: var(--bh-border) !important;
  color: var(--bh-text) !important;
}

.game-card-container:hover,
.item-card-container:hover {
  box-shadow: 0 0 22px var(--bh-glow) !important;
  transform: translateY(-2px);
  transition: .2s ease;
}

.game-card-thumb-container,
.thumbnail-2d-container,
.game-card-thumb { border-radius: 10px !important; }


/* ==========================================================
   4. NAVIGATION
   ========================================================== */

/* --- Top bar --- */
#header, .rbx-header, .navbar-fixed-top, header.navbar, .navbar-full-width {
  background: rgba(12, 19, 44, .88) !important;
  background-image: none !important;
  backdrop-filter: blur(10px);
  border-bottom: 1px solid var(--bh-border) !important;
  box-shadow: 0 2px 20px rgba(0, 0, 0, .35) !important;
}
.nav-menu-title, .font-header-2, .navbar .text-header { color: var(--bh-text) !important; }
.nav-menu-title:hover { color: var(--bh-accent) !important; }

/* --- Left menu: transparent --- */
#left-navigation-container, .rbx-left-col, .left-col-list,
.left-nav, .left-nav > div, .left-nav nav, .left-nav .bg-surface-0 {
  background: transparent !important;
  background-color: transparent !important;
  box-shadow: none !important;
}

#left-navigation-container, .rbx-left-col {
  border-right: 1px solid rgba(38, 52, 99, .45) !important;
}
.left-nav [role="separator"] {
  border-left-color: rgba(38, 52, 99, .45) !important;
}

.left-col-list a, .left-col-list .font-header-2,
.left-nav a, .left-nav button,
.left-nav .content-emphasis, .left-nav .text-title-large { color: var(--bh-text) !important; }
.left-nav .icon { color: var(--bh-accent) !important; }

.left-col-list li:hover, .left-col-list a:hover,
.left-nav a:hover, .left-nav button:hover {
  background: rgba(122, 162, 255, .10) !important;
  color: var(--bh-accent) !important;
}
.left-nav a:hover .icon, .left-nav a:hover span { color: var(--bh-accent-2) !important; }

.left-nav .bg-shift-200 { background: rgba(27, 38, 80, .75) !important; }

/* --- Footer --- */
footer, footer.container-footer, #footer-container, .container-footer, .footer {
  background: transparent !important;
  background-color: transparent !important;
  box-shadow: none !important;
}
footer.container-footer, #footer-container {
  border-top: 1px solid var(--bh-border) !important;
}

.footer .text-footer-nav, .footer-link a { color: var(--bh-accent) !important; }
.footer .text-footer-nav:hover, .footer-link a:hover { color: var(--bh-accent-2) !important; }

.footer .footer-button-link {
  background: transparent !important;
  color: var(--bh-accent) !important;
}
.footer .footer-button-link:hover { color: var(--bh-accent-2) !important; }

.copyright-container { border-top-color: var(--bh-border) !important; }
.footer-note, .text-footer { color: var(--bh-muted) !important; }

.language-selector-wrapper button[role="combobox"] {
  background: var(--bh-bg-2) !important;
  border: 1px solid var(--bh-border) !important;
  color: var(--bh-text) !important;
}
.language-selector-wrapper button[role="combobox"] * { color: var(--bh-text) !important; }
.language-selector-wrapper button[role="combobox"]:hover { border-color: var(--bh-accent) !important; }


/* ==========================================================
   5. TYPOGRAPHY
   ========================================================== */
h1, h2, h3, h4, h5, h6, h2 a, h2 span,
.text-header, .text-lead, .text-label, .text-body, .font-header-1,
.container-header h2, .game-card-name, .item-card-name,
.text-heading-small, .text-heading-medium, .text-heading-large,
.text-title-medium, .text-title-large,
.game-sort-header-container *, .container-header *,
.sort-header *, [class*="sort-header"] *, [class*="SortHeader"] *,
[data-testid*="sort"] h2, [data-testid*="sort"] a {
  color: var(--bh-text) !important;
}

.content-emphasis { color: #e4eaff !important; }
.content-default, .content-standard,
.content-action-standard, .content-action-utility { color: #d6def5 !important; }

.text-secondary, .text-muted, .text-description, .text-caption, .text-footer,
.content-muted, .font-caption-body, .font-caption-header,
.game-card-info, .info-label,
.vote-percentage-label, .playing-counts-label,
.para-overflow, small, .small,
[class*="text-caption"], [class*="caption-"] {
  color: var(--bh-muted) !important;
}

a, a.text-link, a.text-name, .text-link, .btn-link { color: var(--bh-accent) !important; }
a:hover, a.text-link:hover { color: var(--bh-accent-2) !important; }

h2 .icon, .container-header .icon, [class*="sort-header"] .icon { color: var(--bh-accent) !important; }

.game-card-info, .game-card-name, .friend-tile-game-name { opacity: 1 !important; }

.icon-votes-gray, .icon-playing-counts-gray { filter: brightness(1.8) saturate(.6); }


/* ==========================================================
   6. CONTROLS
   ========================================================== */

/* --- Primary buttons --- */
.btn-primary-sm, .btn-primary-md, .btn-primary-lg, .btn-common-play-game-lg,
.btn-cta-sm, .btn-cta-md, .btn-cta-lg, .accept-friend,
.btn-growth-md, .btn-growth-lg,
.btr-game-playbutton {
  background: var(--bh-gradient) !important;
  border: none !important;
  color: #fff !important;
  box-shadow: 0 0 14px var(--bh-glow) !important;
}
.btn-primary-md:hover, .btn-common-play-game-lg:hover,
.btn-cta-md:hover, .accept-friend:hover { filter: brightness(1.15); }

/* --- Secondary buttons / dropdown buttons --- */
.btn-secondary-md, .btn-secondary-lg,
.btn-control-sm, .btn-control-md, .btn-control-lg,
.btn-generic-more-sm,
.input-dropdown-btn, .input-dropdown-btn .rbx-selection-label,
.profile-game-dropdown, [class*="dropdown-btn"] {
  background: var(--bh-raised) !important;
  border: 1px solid var(--bh-border) !important;
  color: var(--bh-text) !important;
}
.btn-secondary-md:hover, .btn-control-md:hover {
  border-color: var(--bh-accent) !important;
  color: var(--bh-accent) !important;
}

/* --- See All --- */
.btn-more.see-all-link-icon, a.see-all-link-icon, .btn-secondary-xs.btn-more {
  background: transparent !important;
  border: none !important;
  box-shadow: none !important;
  color: var(--bh-accent) !important;
}
.btn-more.see-all-link-icon:hover, .btn-secondary-xs.btn-more:hover {
  color: var(--bh-accent-2) !important;
  filter: none;
}

/* --- Get More --- */
.get-more, .get-more *, .get-more-text {
  background: transparent !important;
  color: var(--bh-text) !important;
}

/* --- Inputs --- */
input, textarea, select, .form-control, .input-field, .navbar-search input {
  background: var(--bh-bg-2) !important;
  border: 1px solid var(--bh-border) !important;
  color: var(--bh-text) !important;
}
input:focus, textarea:focus, .form-control:focus {
  border-color: var(--bh-accent) !important;
  box-shadow: 0 0 0 3px var(--bh-glow) !important;
  outline: none !important;
}
::placeholder { color: var(--bh-muted) !important; }

/* --- Dropdown / Modal / Popover --- */
.dropdown-menu, .popover, .modal-content, .modal-dialog .modal-content,
.notification-stream-popover, .foundation-web-menu {
  background: var(--bh-surface) !important;
  border: 1px solid var(--bh-border) !important;
  color: var(--bh-text) !important;
  box-shadow: 0 10px 40px rgba(0, 0, 0, .5) !important;
}
.dropdown-menu li, .dropdown-menu li a {
  background: transparent !important;
  color: var(--bh-text) !important;
}
.dropdown-menu li a:hover, .dropdown-menu li.active a {
  background: var(--bh-raised) !important;
  color: var(--bh-accent) !important;
}
.modal-backdrop { background: #02050f !important; }

[data-radix-popper-content-wrapper] [role="dialog"] { background: transparent !important; }


/* ==========================================================
   7. SEARCH
   ========================================================== */
[data-testid="SearchLandingPageOmniFeedTestId"],
.search-landing-container .game-card-container,
.search-landing-container .game-card-link,
.search-landing-container .scroller,
.search-landing-container .scroller .arrow,
.search-landing-container .scroller .spacer {
  background: transparent !important;
}

/* search popover box (no :has) */
.search-landing-container,
[class*="search-landing"],
[class*="navbar-search"] [class*="dropdown"],
[class*="navbar-search"] [class*="menu"],
.navbar-search .dropdown-menu,
#navbar-universal-search .dropdown-menu,
[role="listbox"],
[data-radix-popper-content-wrapper] > [role="dialog"],
[data-radix-popper-content-wrapper] > [data-state="open"] {
  background: var(--bh-bg-2) !important;
  border: 1px solid var(--bh-border) !important;
  border-radius: 14px !important;
  box-shadow: 0 14px 50px rgba(0, 0, 0, .65), 0 0 20px var(--bh-glow) !important;
  color: var(--bh-text) !important;
}

.search-landing-container .sort-header,
.search-landing-container .sort-header span,
.search-landing-container h2,
.search-landing-container .game-card-name,
.search-landing-container .game-name-title { color: var(--bh-text) !important; }

.search-landing-container .game-card-info,
.search-landing-container .info-label { color: var(--bh-muted) !important; }

.search-landing-container .game-card-container:hover .game-card-name { color: var(--bh-accent) !important; }

/* pill buttons */
.search-pill-carousel-container .bg-shift-300,
.search-pill-carousel-container button {
  background: var(--bh-raised) !important;
  border: 1px solid var(--bh-border) !important;
  color: var(--bh-text) !important;
}
.search-pill-carousel-container button * { color: var(--bh-text) !important; }
.search-pill-carousel-container button:hover {
  background: #243268 !important;
  border-color: var(--bh-accent) !important;
}
.search-pill-carousel-container button:hover * { color: var(--bh-accent) !important; }

.search-landing-container .scroller .arrow span,
.search-landing-container .icon-games-carousel-right { filter: var(--bh-icon-tint); }

/* search results */
.navbar-list-option-text,
.new-navbar-search-anchor .navbar-list-option-text { color: #e4eaff !important; }
.navbar-list-option-suffix,
.new-navbar-search-anchor .navbar-list-option-suffix { color: var(--bh-muted) !important; }
.navbar-list-option-icon { color: var(--bh-accent) !important; }
.new-navbar-search-anchor,
.new-navbar-search-anchor span { opacity: 1 !important; }
.new-navbar-search-anchor:hover { background: var(--bh-raised) !important; }
.new-navbar-search-anchor:hover .navbar-list-option-text { color: var(--bh-accent) !important; }


/* ==========================================================
   8. CHAT AND FRIENDS
   ========================================================== */
section[aria-label="Chat"],
section.react-chat-dialog-shell {
  --color-surface-100: var(--bh-bg-2) !important;
  --color-surface-300: var(--bh-raised) !important;
  background: var(--bh-bg-2) !important;
  border: 1px solid var(--bh-border) !important;
  border-bottom: none !important;
  border-radius: 12px 12px 0 0 !important;
  box-shadow: 0 -4px 30px rgba(0, 0, 0, .6), 0 0 18px var(--bh-glow) !important;
  color: var(--bh-text) !important;
}

section[aria-label="Chat"] > div,
section[aria-label="Chat"] .react-chat-thread-list,
section[aria-label="Chat"] [class*="bg-surface-100"],
section.react-chat-dialog-shell > div,
section.react-chat-dialog-shell .bg-surface-100,
.react-chat-dialog-header,
.react-chat-dialog-scroll,
.react-chat-dialog-scroll ul,
[class*="react-chat"][class*="window"],
[class*="react-chat-conversation"],
[class*="react-chat-message"],
[class*="react-chat-composer"],
[class*="react-chat-header"] {
  background: var(--bh-bg-2) !important;
  color: var(--bh-text) !important;
}

.react-chat-dialog-header { border-bottom: 1px solid var(--bh-border) !important; }

section[aria-label="Chat"] [data-testid="text-input-container"] {
  background: var(--bh-bg) !important;
  border: 1px solid var(--bh-border) !important;
  border-radius: 10px !important;
}
section[aria-label="Chat"] input {
  background: transparent !important;
  border: none !important;
  box-shadow: none !important;
}

section[aria-label="Chat"] .react-chat-row { background: transparent !important; }
section[aria-label="Chat"] .react-chat-row:hover { background: var(--bh-raised) !important; }

section[aria-label="Chat"] .react-chat-row-title,
section[aria-label="Chat"] .content-emphasis,
.react-chat-dialog-title,
section.react-chat-dialog-shell .content-emphasis { color: var(--bh-text) !important; }

section[aria-label="Chat"] .react-chat-row-preview,
section[aria-label="Chat"] .content-muted,
section.react-chat-dialog-shell .content-muted { color: var(--bh-muted) !important; }

section[aria-label="Chat"] .icon,
section.react-chat-dialog-shell .icon { color: var(--bh-accent) !important; }

section[aria-label="Chat"] .react-chat-presence-dot {
  border-color: var(--bh-bg-2) !important;
  --color-surface-100: var(--bh-bg-2) !important;
}

/* message bubbles */
.react-chat-message-bubble-incoming {
  background: var(--bh-raised) !important;
  color: var(--bh-text) !important;
}
.react-chat-message-bubble-outgoing {
  background: var(--bh-gradient) !important;
  color: #fff !important;
}
.react-chat-message-bubble-outgoing * { color: #fff !important; }

/* message input */
.react-chat-message-input-textarea {
  background: var(--bh-bg) !important;
  border: 1px solid var(--bh-border) !important;
  border-radius: 14px !important;
  color: var(--bh-text) !important;
}
.react-chat-message-input-textarea:focus {
  border-color: var(--bh-accent) !important;
  box-shadow: 0 0 0 3px var(--bh-glow) !important;
}

/* friend tile menu */
.friend-tile-dropdown {
  background: var(--bh-surface) !important;
  border: 1px solid var(--bh-border) !important;
  border-radius: 12px !important;
  box-shadow: 0 10px 40px rgba(0, 0, 0, .6), 0 0 16px var(--bh-glow) !important;
  overflow: hidden;
}
.friend-tile-dropdown ul, .friend-tile-dropdown li { background: transparent !important; }
.friend-tile-dropdown-button {
  background: transparent !important;
  color: var(--bh-text) !important;
}
.friend-tile-dropdown-button:hover {
  background: var(--bh-raised) !important;
  color: var(--bh-accent) !important;
}
.friend-tile-dropdown-button span { filter: var(--bh-icon-tint); opacity: .9; }

/* in-game friend card */
.in-game-friend-card--iarc {
  background: var(--bh-surface) !important;
  border: 1px solid var(--bh-border) !important;
  border-radius: 14px !important;
  box-shadow: 0 10px 40px rgba(0, 0, 0, .6), 0 0 16px var(--bh-glow) !important;
}

.friend-tile-is-playing,
.friend-tile-game-name, .friend-tile-game-name *,
.friends-carousel-tile-labels, .friends-carousel-tile-experience,
[class*="friend-tile"] .text-secondary,
[class*="friend-tile"] [class*="game"],
[class*="friend-tile"] [class*="label"] { color: var(--bh-muted) !important; }

.in-game-friend-card-actions .bg-action-standard,
.in-game-friend-card-actions button.content-action-standard {
  background: var(--bh-raised) !important;
  border: 1px solid var(--bh-border) !important;
  color: var(--bh-text) !important;
}
.in-game-friend-card-actions .bg-action-standard *,
.in-game-friend-card-actions button.content-action-standard * { color: var(--bh-text) !important; }
.in-game-friend-card-actions .bg-action-standard:hover { border-color: var(--bh-accent) !important; }
.in-game-friend-card-actions .bg-action-standard:hover * { color: var(--bh-accent) !important; }

/* Join button (delete this block to keep the original green) */
.in-game-friend-card-actions .bg-action-emphasis {
  background: var(--bh-gradient) !important;
  box-shadow: 0 0 14px var(--bh-glow) !important;
}
.in-game-friend-card-actions .bg-action-emphasis * { color: #fff !important; }

.in-game-friend-card-actions .foundation-web-link { color: var(--bh-text) !important; }
.in-game-friend-card-actions .foundation-web-link:hover { color: var(--bh-accent) !important; }


/* ==========================================================
   9. GAMES / BADGES
   ========================================================== */
.badge-name, .badge-name a, .badge-row a { color: var(--bh-accent) !important; }

.badge-row p, .badge-row .para-overflow, .badge-row .text-label,
.badge-row .text-secondary, .badge-row .font-caption-body,
.badge-row .font-caption-header, .badge-row .badge-stats-info,
.badge-row .badge-content p, .badge-row .badge-data-container p,
.badge-row [class*="unlock"], .badge-row [class*="Unlock"] {
  color: var(--bh-muted) !important;
}


/* ==========================================================
   10. INVENTORY
   ========================================================== */
.row.page-content, .page-content, .content > .row, #content .row, #content .content > div,
assets-explorer, assets-explorer > div,
.assets-explorer-main-content, .assets-explorer-title, .header-content,
.rbx-tabs-vertical, .col-xs-12.rbx-tabs-vertical,
.rbx-tabs-vertical .tab-content, .rbx-tabs-vertical .rbx-tab-content,
.menu-vertical-container, .menu-vertical-container.category-tabs,
#vertical-menu, ul#vertical-menu, .menu-vertical, .menu-vertical.submenus, .menu-vertical li,
.current-items, .item-cards, .item-cards-embed,
#item-recommendations-container, #item-recommendations-container .current-items,
.recommendations-container, .recommended-items-slider {
  background: transparent !important;
  background-image: none !important;
  box-shadow: none !important;
  border-color: var(--bh-border) !important;
}

/* category menu */
.menu-option, .menu-option-content, .menu-vertical .menu-option {
  background: transparent !important;
  color: var(--bh-text) !important;
}
.menu-vertical .menu-option:hover { background: var(--bh-raised) !important; }
.menu-vertical .menu-option.active,
.menu-vertical .menu-option.active > .menu-option-content {
  background: var(--bh-surface) !important;
  border-left: 3px solid var(--bh-accent) !important;
}
.menu-text, .menu-option .menu-text, .menu-secondary-option .menu-text,
.menu-vertical-container h2, .category-dropdown h2, .subcategory-dropdown h2 {
  color: var(--bh-text) !important;
}
.menu-option .icon-right-16x16 { filter: var(--bh-icon-tint); }

/* submenu popout */
.menu-secondary-container {
  background: var(--bh-bg-2) !important;
  border: 1px solid var(--bh-border) !important;
  border-radius: 10px !important;
