/* ==========================================================
   21. FIXES: stuck green alert, cart checkbox, transaction dropdowns
   ========================================================== */

/* --- Stuck green "added to cart" bar ---
   backdrop-filter on .catalog-header made it the containing block of the
   alert (position: fixed), so the alert never slid away. The blur now lives
   on a pseudo-element, which does not trap fixed children. */
.catalog-header {
  backdrop-filter: none !important;
  -webkit-backdrop-filter: none !important;
  isolation: isolate;
}
.catalog-header::before {
  content: "";
  position: absolute;
  top: 0;
  right: 0;
  bottom: 0;
  left: 0;
  z-index: -1;
  pointer-events: none;
  backdrop-filter: blur(16px);
  -webkit-backdrop-filter: blur(16px);
}
/* the alert itself, in theme colors */
.alert-system-feedback .alert,
.alert-system-feedback .alert.alert-success,
.alert-success {
  background: rgba(34, 94, 66, .92) !important;
  border: 1px solid rgba(159, 224, 176, .35) !important;
  color: #d8f6e0 !important;
  border-radius: 0 0 10px 10px !important;
  box-shadow: 0 6px 24px rgba(0, 0, 0, .45) !important;
}
.alert-system-feedback .alert *, .alert-success * { color: #d8f6e0 !important; }

/* --- Checkbox (cart and other legacy checkboxes) --- */
.checkbox input[type="checkbox"] + label,
.purchase-checkbox-container label,
.purchase-checkbox-container .input-checkbox + label {
  background: transparent !important;
  border: none !important;
  box-shadow: none !important;
}
.checkbox input[type="checkbox"] + label::before,
.purchase-checkbox-container label::before {
  background: rgba(122, 162, 255, .08) !important;
  border: 1.5px solid rgba(122, 162, 255, .45) !important;
  border-radius: 6px !important;
  box-shadow: none !important;
  transition: background .15s ease, border-color .15s ease, box-shadow .15s ease;
}
.checkbox input[type="checkbox"]:hover + label::before,
.purchase-checkbox-container label:hover::before {
  border-color: var(--bh-accent) !important;
}
.checkbox input[type="checkbox"]:checked + label::before,
.purchase-checkbox-container .input-checkbox:checked + label::before {
  background: var(--bh-gradient) !important;
  border-color: transparent !important;
  box-shadow: 0 0 10px var(--bh-glow) !important;
}
.checkbox input[type="checkbox"]:checked + label::after,
.purchase-checkbox-container .input-checkbox:checked + label::after {
  border-color: #fff !important;
  color: #fff !important;
}

/* --- Dropdowns on the transactions page (and any .dropdown-btn wrapper) --- */
div.dropdown-btn,
.transaction-type-dropdown, .transaction-date-dropdown {
  background: transparent !important;
  border: none !important;
  box-shadow: none !important;
}
.dropdown-btn .font-caption-header, .dropdown-btn label { color: var(--bh-muted) !important; }
.dropdown-btn .input-dropdown-btn {
  background: rgba(15, 23, 48, .35) !important;
  border: 1px solid rgba(38, 52, 99, .6) !important;
  color: var(--bh-text) !important;
  box-shadow: none !important;
}
.dropdown-btn .input-dropdown-btn:hover { border-color: rgba(122, 162, 255, .45) !important; }
.input-dropdown-btn .rbx-selection-label {
  background: transparent !important;
  border: none !important;
  box-shadow: none !important;
  outline: none !important;
}
.icon-down-16x16 { filter: var(--bh-icon-tint); }

/* ==========================================================
   22. MUI DIALOGS / ALL DIALOGS SOLID + BRIGHTER TEXT
   ========================================================== */

/* generic dialogs: low specificity on purpose, so the search popover rule
   in section 6 ([data-radix-popper-content-wrapper] [role="dialog"]) still wins */
[role="dialog"],
.MuiDialog-paper, .MuiPaper-root.MuiDialog-paper {
