}
.MuiDialog-paper *, [role="dialog"] .MuiPaper-root { opacity: 1; }

/* group description dialog */
.group-description-dialog-header, .group-description-dialog-body {
  background: transparent !important;
}
.group-description-dialog-title,
.group-description-dialog-body-header { color: #eef2ff !important; }
.group-description-dialog-body-content,
.group-description-dialog-body pre { color: var(--bh-text) !important; background: transparent !important; }
.group-description-dialog-close {
