}
.social-link-btn:hover { border-color: rgba(122, 162, 255, .5) !important; }
.social-link-btn *, .social-link-icon { color: var(--bh-text) !important; }

/* close buttons (white circles) in any dialog */
[role="dialog"] button[aria-label="Close"],
.foundation-web-close-affordance,
.fui-sheet-close-affordance-container button {
  background: rgba(122, 162, 255, .10) !important;
  border: 1px solid var(--bh-border) !important;
  box-shadow: none !important;
}
[role="dialog"] button[aria-label="Close"] .icon,
[role="dialog"] button[aria-label="Close"] svg { color: var(--bh-text) !important; fill: var(--bh-text) !important; }

/* general body text: brighter */
.text-body-medium:not(a), .text-body-small:not(a),
.text-caption-medium:not(a), .text-caption-small:not(a),
p, pre, li, label {
  color: var(--bh-text);
}
.text-heading-small, .text-heading-medium, .text-heading-large,
.text-title-small, .text-title-medium, .text-title-large,
.text-display-small, .text-display-medium, .text-display-large { color: #eef2ff !important; }

/* ==========================================================
   23. CART CHECKBOX (round, stays inside its frame) + NOTIFICATIONS
   ========================================================== */

/* checkbox: fixed size, round like the radio buttons elsewhere */
.purchase-checkbox-container .checkbox,
.purchase-checkbox-container.checkbox { overflow: visible; }
.purchase-checkbox-container label,
.checkbox .input-checkbox + label {
  position: relative !important;
  display: block !important;
  width: 22px !important;
  height: 22px !important;
  margin: 0 !important;
  padding: 0 !important;
  background: transparent !important;
  border: none !important;
  box-shadow: none !important;
  cursor: pointer;
}
.purchase-checkbox-container label::before,
.checkbox .input-checkbox + label::before {
  content: "" !important;
  position: absolute !important;
  top: 0 !important;
  right: 0 !important;
  bottom: 0 !important;
  left: 0 !important;
  width: 100% !important;
  height: 100% !important;
  box-sizing: border-box !important;
  margin: 0 !important;
  border-radius: 50% !important;
  background: rgba(122, 162, 255, .06) !important;
  background-image: none !important;
  border: 1.5px solid rgba(122, 162, 255, .35) !important;
  box-shadow: none !important;
}
.purchase-checkbox-container label:hover::before,
.checkbox .input-checkbox + label:hover::before { border-color: var(--bh-accent) !important; }
.purchase-checkbox-container .input-checkbox:checked + label::before,
.checkbox .input-checkbox:checked + label::before {
  background: var(--bh-gradient) !important;
  border-color: transparent !important;
  box-shadow: 0 0 10px var(--bh-glow) !important;
}
/* check mark, drawn by us */
.purchase-checkbox-container .input-checkbox:checked + label::after,
.checkbox .input-checkbox:checked + label::after {
  content: "" !important;
  position: absolute !important;
  left: 7px !important;
  top: 3.5px !important;
  width: 5px !important;
  height: 10px !important;
  border: solid #fff !important;
  border-width: 0 2px 2px 0 !important;
  border-radius: 0 !important;
  background: none !important;
  transform: rotate(45deg) !important;
  box-shadow: none !important;
}

/* notifications panel */
.notification-stream-base {
  background: var(--bh-bg-2) !important;
  border: 1px solid var(--bh-border) !important;
  border-radius: 14px !important;
  box-shadow: 0 14px 50px rgba(0, 0, 0, .65), 0 0 20px var(--bh-glow) !important;
}
.notification-stream-header {
  background: transparent !important;
  border-bottom: 1px solid var(--bh-border) !important;
}
.foundation-web-notification {
  background: rgba(122, 162, 255, .04) !important;
  border: 1px solid rgba(38, 52, 99, .5) !important;
  box-shadow: none !important;
}
.foundation-web-notification:hover { background: rgba(122, 162, 255, .08) !important; }

/* "2 more" bundle pill + the stacked white edges */
.notification-bundle .bundle-button,
.bundle-button.closed, .bundle-button {
  background: rgba(122, 162, 255, .16) !important;
  border: 1px solid var(--bh-border) !important;
  color: var(--bh-text) !important;
  box-shadow: none !important;
}
.bundle-button *, .bundle-button-label { color: var(--bh-text) !important; }
.bundle-button .icon-down-16x16 { filter: var(--bh-icon-tint); }
.notification-bundle.multiple-shadows,
.notification-bundle.closed {
  box-shadow: none !important;
}
.notification-bundle.multiple-shadows::before,
.notification-bundle.multiple-shadows::after,
.notification-bundle.closed::before,
.notification-bundle.closed::after {
  background: var(--bh-raised) !important;
  border: 1px solid rgba(38, 52, 99, .6) !important;
  box-shadow: none !important;
}
.notification-bundle .sendr-notification-background { box-shadow: none !important; }

/* notification buttons */
.sendr-notification-button--primary,
.sendr-notification-button--secondary {
  background: rgba(122, 162, 255, .10) !important;
  border: 1px solid var(--bh-border) !important;
  box-shadow: none !important;
}
.sendr-notification-button--primary *,
.sendr-notification-button--secondary * { color: var(--bh-text) !important; }
.sendr-notification-button--growth {
  background: var(--bh-gradient) !important;
  border: none !important;
  box-shadow: none !important;
}
.sendr-notification-button--growth * { color: #fff !important; }

/* ==========================================================
   24. NATIVE <select> DROPDOWN LISTS
   ========================================================== */
select, .rbx-select, select.input-field {
  color-scheme: dark;
}
select option, select optgroup,
.rbx-select option, .select-option option {
  background-color: #0f1730 !important;
  background-image: none !important;
  color: #e0e7fb !important;
}
select option:hover, select option:focus,
select option:checked, .rbx-select option:checked {
  background-color: #243268 !important;
  color: #ffffff !important;
}
select option:disabled { color: var(--bh-muted) !important; }

/* ==========================================================
   26. FIX: blurred text on the Avatar page + slider
   Cause: the Avatar page also has a ".catalog-header" element. Its ::before
   (blur layer from section 21) was not confined to it, so it blurred the
   whole page behind it. Now it is positioned relative to its own header.
   ========================================================== */
.catalog-header { position: relative; }   /* no !important: Marketplace's inline sticky still wins */

.avatar-editor-header .catalog-header {
  background: transparent !important;
  border: none !important;
  box-shadow: none !important;
  isolation: auto;
}
.avatar-editor-header .catalog-header::before { display: none !important; }

/* sliders (Body Type, Height, Width ...) */
.foundation-web-slider > span:first-child {
  background: rgba(122, 162, 255, .18) !important;
}
.foundation-web-slider > span:first-child > span {
  background: var(--bh-gradient) !important;
}
.foundation-web-slider [role="slider"] {
  background: var(--bh-accent) !important;
  border: 2px solid var(--bh-bg-2) !important;
  box-shadow: 0 0 10px var(--bh-glow) !important;
}
.scale-container .scale-label, .scale-container .text-label { color: var(--bh-text) !important; }

/* ==========================================================
   27. DIM TEXT BRIGHTENING (game page: votes, store prices, Buy ...)
   ========================================================== */

/* classes Roblox uses for dim/disabled text */
.content-disabled, .content-subtle, .content-secondary, .content-tertiary,
.text-disabled, .text-subtle, .text-tertiary,
[class*="content-disabled"], [class*="content-subtle"], [class*="content-secondary"],
[class*="text-secondary"], [class*="text-disabled"] {
  color: var(--bh-muted) !important;
  opacity: 1 !important;
}

/* vote bar numbers (3M+ / 253K+) */
.vote-numbers, .vote-numbers *, .vote-details, .vote-details *,
.count-left, .count-right, .vote-count, .vote-container .text-label,
[class*="vote-"] [class*="count"], [class*="vote"] [class*="number"] {
  color: var(--bh-muted) !important;
  opacity: 1 !important;
}
.vote-container .vote-percentage-label, .vote-percentage-label { color: var(--bh-text) !important; }

/* store (passes / items for sale): name, price, Buy */
[class*="store-card"], [class*="store-card"] * {
  opacity: 1;
}
[class*="store-card"] [class*="name"], [class*="store-card-name"] { color: var(--bh-text) !important; }
[class*="store-card"] [class*="price"], [class*="store-card"] [class*="price"] *,
.store-card-price, .store-card-price *,
.text-robux, .text-robux-lg { color: var(--bh-green) !important; opacity: 1 !important; }
[class*="store-card"] button, [class*="store-card"] .btn-buy,
.store-card-footer button, .btn-buy-md, .btn-buy-lg {
  background: rgba(122, 162, 255, .10) !important;
  border: 1px solid var(--bh-border) !important;
  color: var(--bh-text) !important;
  opacity: 1 !important;
  box-shadow: none !important;
}
[class*="store-card"] button:hover, .btn-buy-md:hover { border-color: var(--bh-accent) !important; color: var(--bh-accent) !important; }
[class*="store-card"] button *, .btn-buy-md * { color: inherit !important; }

/* disabled buttons: readable, but still clearly disabled */
button:disabled, button[disabled], [aria-disabled="true"] { opacity: .75 !important; }

/* page-wide: small gray captions and labels */
.text-caption, .text-caption-small, .text-caption-medium,
.font-caption-body, .font-caption-header, .text-footer, .text-description,
.text-muted, .content-muted, small, .small { color: var(--bh-muted) !important; opacity: 1 !important; }

/* ==========================================================
   28. DARK ICONS -> LIGHT (votes, players, arrows, chevrons ...)
   ========================================================== */

/* old sprite icons drawn in gray/black */
.icon-votes-gray, .icon-playing-counts-gray, .icon-votes, .icon-playing-counts,
[class*="icon-"][class*="-gray"], [class*="icon-"][class*="-black"],
.icon-arrow-right, .icon-right, .icon-left, .icon-down, .icon-up,
[class*="icon-chevron"], [class*="icon-arrow"], .icon-more,
.icon-nav-charts, .icon-close, .icon-close-gray {
  filter: var(--bh-icon-tint) !important;
  opacity: .85;
}

/* new Foundation icons (mask/currentColor): light by default.
   Colored ones (verified badge, success, alert ...) are excluded. */
.icon:not([class*="system-"]):not([class*="alert"]):not([class*="success"]):not([class*="warning"]):not([class*="verified"]) {
  color: #b4c0e6 !important;
}
/* arrows next to section titles ("Up-and-Coming  ->") */
h2 .icon, .container-header .icon, [class*="sort-header"] .icon,
a .icon-regular-arrow-right, [class*="icon-regular-arrow"], [class*="icon-regular-chevron"] {
  color: var(--bh-accent) !important;
}

/* numbers next to the icons (96%, 83.1K ...) */
.vote-percentage-label, .playing-counts-label, .info-label,
[class*="game-card"] [class*="label"] { color: #dbe3fb !important; opacity: 1 !important; }

/* ==========================================================
   29. TOOLTIPS, MUI MENUS, DARK TEXT INSIDE DIALOGS
   ========================================================== */

/* tooltips: ONE box only (outermost element), everything inside is plain */
.tooltip-inner,
[role="tooltip"],
.popover,
.MuiTooltip-tooltip,
[data-radix-popper-content-wrapper] > [class*="tooltip"],
body > [class*="tooltip"]:not(.tooltip):not([class*="container"]):not([class*="icon"]) {
  background: var(--bh-surface) !important;
  background-image: none !important;
  border: 1px solid var(--bh-border) !important;
  border-radius: 10px !important;
  color: var(--bh-text) !important;
  box-shadow: 0 10px 30px rgba(0, 0, 0, .6) !important;
  opacity: 1 !important;
}
/* inner wrappers: no extra boxes (this removes the stacked frames) */
.tooltip-inner *,
[role="tooltip"] *,
.popover *,
.MuiTooltip-tooltip *,
[data-radix-popper-content-wrapper] > [class*="tooltip"] *,
body > [class*="tooltip"]:not(.tooltip) * {
  background: transparent !important;
  background-image: none !important;
  border: none !important;
  border-radius: 0 !important;
  box-shadow: none !important;
  color: var(--bh-text) !important;
  opacity: 1 !important;
}
.tooltip-arrow { background: transparent !important; }
.tooltip.top .tooltip-arrow { border-top-color: var(--bh-surface) !important; }
.tooltip.bottom .tooltip-arrow { border-bottom-color: var(--bh-surface) !important; }
.tooltip.left .tooltip-arrow { border-left-color: var(--bh-surface) !important; }
.tooltip.right .tooltip-arrow { border-right-color: var(--bh-surface) !important; }
.tooltip { opacity: 1; }

/* MUI popup menus (community "..." menu: Make Primary, Leave, Copy link ...) */
.MuiPopover-paper, .MuiMenu-paper, .MuiPaper-root.MuiPopover-paper,
.MuiAutocomplete-paper, .MuiPickersPopper-paper {
  background: var(--bh-bg-2) !important;
  background-image: none !important;
  border: 1px solid var(--bh-border) !important;
  border-radius: 12px !important;
  box-shadow: 0 14px 40px rgba(0, 0, 0, .65), 0 0 16px var(--bh-glow) !important;
  color: var(--bh-text) !important;
}
.MuiList-root, .MuiMenu-list { background: transparent !important; }
.MuiMenuItem-root, .contextual-menu-actions-menu-item {
  background: transparent !important;
  color: var(--bh-text) !important;
  opacity: 1 !important;
}
.MuiMenuItem-root:hover, .MuiMenuItem-root.Mui-focusVisible,
.contextual-menu-actions-menu-item:hover {
  background: rgba(122, 162, 255, .12) !important;
  color: var(--bh-accent) !important;
}
.MuiDivider-root { border-color: var(--bh-border) !important; }

/* dark titles / text inside dialogs ("How to trade" steps ...) */
.foundation-web-dialog-content h1,
.foundation-web-dialog-content h2,
.foundation-web-dialog-content h3,
.foundation-web-dialog-content h4,
.foundation-web-dialog-content b,
.foundation-web-dialog-content strong,
.foundation-web-dialog-content p,
.foundation-web-dialog-content li,
.foundation-web-dialog-content span,
.foundation-web-dialog-content div,
.fui-base-sheet-content h1,
.fui-base-sheet-content h2,
.fui-base-sheet-content h3,
.fui-base-sheet-content h4,
.fui-base-sheet-content b,
.fui-base-sheet-content strong,
.fui-base-sheet-content p,
.fui-base-sheet-content li,
.fui-base-sheet-content span,
.fui-base-sheet-content div,
.MuiDialog-paper h1,
.MuiDialog-paper h2,
.MuiDialog-paper h3,
.MuiDialog-paper h4,
.MuiDialog-paper b,
.MuiDialog-paper strong,
.MuiDialog-paper p,
.MuiDialog-paper li,
.MuiDialog-paper span,
.MuiDialog-paper div {
  color: var(--bh-text) !important;
  opacity: 1 !important;
}
.foundation-web-dialog-content h1,
.foundation-web-dialog-content h2,
.foundation-web-dialog-content h3,
.foundation-web-dialog-content h4,
.foundation-web-dialog-content b,
.foundation-web-dialog-content strong,
.foundation-web-dialog-content [class*="title"],
.foundation-web-dialog-content [class*="heading"],
.foundation-web-dialog-content [class*="emphasis"],
.fui-base-sheet-content h1,
.fui-base-sheet-content h2,
.fui-base-sheet-content h3,
.fui-base-sheet-content h4,
.fui-base-sheet-content b,
.fui-base-sheet-content strong,
.fui-base-sheet-content [class*="title"],
.fui-base-sheet-content [class*="heading"],
.fui-base-sheet-content [class*="emphasis"],
.MuiDialog-paper h1,
.MuiDialog-paper h2,
.MuiDialog-paper h3,
.MuiDialog-paper h4,
.MuiDialog-paper b,
.MuiDialog-paper strong,
.MuiDialog-paper [class*="title"],
.MuiDialog-paper [class*="heading"],
.MuiDialog-paper [class*="emphasis"] {
  color: #eef2ff !important;
}
/* text on buttons inside dialogs: white, not dim blue */
.foundation-web-dialog-content button *,
.foundation-web-dialog-content a.foundation-web-button *,
.fui-base-sheet-content button *,
.fui-base-sheet-content a.foundation-web-button *,
.MuiDialog-paper button *,
.MuiDialog-paper a.foundation-web-button * {
  color: #fff !important;
  opacity: 1 !important;
}
.foundation-web-dialog-content button .icon,
.fui-base-sheet-content button .icon { color: #fff !important; }

/* ==========================================================
   30. TOP BAR: BTRoblox friends / messages icons + Plus badge
   Cause: the "transparent containers" rule in section 3 matched
   [class*="friend-"] and wiped the sprite of .icon-nav-friend-btr.
   (that selector now skips elements whose class contains "icon")
   ========================================================== */
.icon-nav-friend-btr, .icon-nav-message-btr {
  filter: var(--bh-icon-tint);
  opacity: .9;
}
.icon-nav-friend-btr:hover, .icon-nav-message-btr:hover { opacity: 1; }

.btr-nav-notif {
  background: var(--bh-raised) !important;
  border: 1px solid var(--bh-border) !important;
  color: #fff !important;
}

/* Roblox Plus badge next to the username */
.age-bracket-label-plus-badge .icon,
.age-bracket-label-plus-badge [class*="content-system"] {
  color: var(--bh-accent) !important;
  opacity: 1 !important;
}

/* ==========================================================
   31. TOP BAR: friends / messages icons - white like Robux + settings,
   and vertically centered in the bar
   ========================================================== */
#btr-navbar-friends, #btr-navbar-messages {
  display: flex !important;
  align-items: center !important;
  justify-content: center !important;
  height: 40px !important;
  margin: 0 !important;
  padding: 0 !important;
  vertical-align: middle !important;
}
#btr-navbar-friends > a, #btr-navbar-messages > a {
  position: relative !important;
  display: flex !important;
  align-items: center !important;
  justify-content: center !important;
  height: 40px !important;
  margin: 0 !important;
  padding: 0 6px !important;
  line-height: 1 !important;
}
.icon-nav-friend-btr, .icon-nav-message-btr {
  position: static !important;
  margin: 0 !important;
  flex-shrink: 0;
  vertical-align: middle !important;
  filter: brightness(0) invert(1) !important;   /* pure white, same as the Robux / gear icons */
  opacity: 1 !important;
}
/* count bubbles stay at the top-right of each icon */
#btr-navbar-friends .btr-nav-notif, #btr-navbar-messages .btr-nav-notif {
  position: absolute !important;
  top: 0 !important;
  right: -2px !important;
}

/* ==========================================================
   33. CHAT WIDGET - not dependent on aria-label
   Cause: page translation changes aria-label="Chat" to a translated word
   (e.g. aria-label="..."), so the section 8 rules, which select
   section[aria-label="Chat"], stopped matching. These use classes instead.
   ========================================================== */
section.react-chat-top-radius {
  --color-surface-100: var(--bh-bg-2);
  --color-surface-300: var(--bh-raised);
  background: var(--bh-bg-2) !important;
  background-image: none !important;
  border: 1px solid var(--bh-border) !important;
  border-bottom: none !important;
  border-radius: 12px 12px 0 0 !important;
  box-shadow: 0 -4px 30px rgba(0, 0, 0, .6), 0 0 18px var(--bh-glow) !important;
  color: var(--bh-text) !important;
  opacity: 1 !important;
}
section.react-chat-top-radius > div,
section.react-chat-top-radius .bg-surface-100,
section.react-chat-top-radius .react-chat-thread-list {
  background: var(--bh-bg-2) !important;
  color: var(--bh-text) !important;
}
section.react-chat-top-radius [data-testid="text-input-container"] {
  background: var(--bh-bg) !important;
  border: 1px solid var(--bh-border) !important;
  border-radius: 10px !important;
}
section.react-chat-top-radius input {
  background: transparent !important;
  border: none !important;
  box-shadow: none !important;
  color: var(--bh-text) !important;
}
section.react-chat-top-radius .react-chat-row { background: transparent !important; }
section.react-chat-top-radius .react-chat-row:hover { background: var(--bh-raised) !important; }
section.react-chat-top-radius .react-chat-row-title,
section.react-chat-top-radius .content-emphasis,
section.react-chat-top-radius .content-emphasis font { color: var(--bh-text) !important; }
section.react-chat-top-radius .react-chat-row-preview,
section.react-chat-top-radius .content-muted { color: var(--bh-muted) !important; }
section.react-chat-top-radius .icon { color: var(--bh-accent) !important; }
section.react-chat-top-radius .react-chat-presence-dot {
  border-color: var(--bh-bg-2) !important;
  --color-surface-100: var(--bh-bg-2);
}
section.react-chat-top-radius .foundation-web-icon-button { background: transparent !important; }

/* ==========================================================
   34. FOUNDATION BUTTONS: readable labels (Join / Create ...)
   ========================================================== */

/* green buttons (Join): brighter green, white label */
[class*="bg-system-success"], [class*="bg-success"], .btn-success-md, .btn-success-lg,
.foundation-web-button[class*="success"], button[class*="success"], a[class*="success"] {
  background: linear-gradient(135deg, #2f9e6e, #3dbb8c) !important;
  border: none !important;
  color: #fff !important;
  box-shadow: none !important;
  opacity: 1 !important;
}
[class*="bg-system-success"] *, [class*="bg-success"] *, .btn-success-md *, .btn-success-lg *,
.foundation-web-button[class*="success"] *, button[class*="success"] *, a[class*="success"] * {
  color: #fff !important;
  opacity: 1 !important;
}

/* standard buttons (Create ...): soft blue fill, light label */
.foundation-web-button.bg-action-standard {
  background: rgba(122, 162, 255, .12) !important;
  border: 1px solid var(--bh-border) !important;
  color: #e8eeff !important;
  box-shadow: none !important;
  opacity: 1 !important;
}
.foundation-web-button.bg-action-standard * { color: #e8eeff !important; opacity: 1 !important; }
.foundation-web-button.bg-action-standard:hover {
  background: rgba(122, 162, 255, .20) !important;
  border-color: rgba(122, 162, 255, .5) !important;
}

/* emphasis buttons: gradient, white label */
.foundation-web-button.bg-action-emphasis {
  background: var(--bh-gradient) !important;
  border: none !important;
  box-shadow: none !important;
  opacity: 1 !important;
}
.foundation-web-button.bg-action-emphasis * { color: #fff !important; opacity: 1 !important; }

/* small list text under server names */
.text-body-medium, .text-caption-medium { opacity: 1 !important; }

/* ==========================================================
   35. BTRoblox body-scale popup (avatar viewer) + darkest-text tokens
   ========================================================== */

/* the popup was white, with our light text on top of it */
.btr-thumb-popup, .btr-body-popup {
  background: var(--bh-bg-2) !important;
  background-image: none !important;
  border: 1px solid var(--bh-border) !important;
  border-radius: 12px !important;
  box-shadow: 0 14px 40px rgba(0, 0, 0, .65), 0 0 16px var(--bh-glow) !important;
  color: var(--bh-text) !important;
}
.btr-thumb-popup::before, .btr-thumb-popup::after,
.btr-body-popup::before, .btr-body-popup::after { border-right-color: var(--bh-bg-2) !important; border-left-color: transparent; }
.btr-thumb-popup div, .btr-body-popup div { background: transparent !important; }
.btr-thumb-popup label, .btr-body-popup label, .btr-outfit-header { color: var(--bh-text) !important; opacity: 1 !important; }
.btr-thumb-popup label.value, .btr-body-popup label.value { color: var(--bh-muted) !important; }
.btr-body-outfit-title { color: var(--bh-text) !important; }
.btr-body-outfit-icon { background: var(--bh-surface) !important; border-radius: 10px !important; overflow: hidden; }
.btr-body-outfit-btn.selected .btr-body-outfit-icon { box-shadow: 0 0 0 2px var(--bh-accent) !important; }

/* sliders: one clean track, filled part in accent, round thumb */
.btr-thumb-popup input[type="range"], .btr-body-popup input[type="range"] {
  -webkit-appearance: none;
  appearance: none;
  height: 6px !important;
  padding: 0 !important;
  border: none !important;
  border-radius: 6px !important;
  box-shadow: none !important;
  outline: none !important;
  background: linear-gradient(to right, var(--bh-accent) 0%, var(--bh-accent-2) var(--btr-input-perc, 0%), rgba(122, 162, 255, .18) var(--btr-input-perc, 0%), rgba(122, 162, 255, .18) 100%) !important;
}
.btr-thumb-popup input[type="range"]::-webkit-slider-runnable-track,
.btr-body-popup input[type="range"]::-webkit-slider-runnable-track { background: transparent !important; height: 6px; border: none !important; }
.btr-thumb-popup input[type="range"]::-webkit-slider-thumb,
.btr-body-popup input[type="range"]::-webkit-slider-thumb {
  -webkit-appearance: none;
  width: 16px; height: 16px; margin-top: -5px;
  border-radius: 50%;
  background: var(--bh-accent) !important;
  border: 2px solid var(--bh-bg-2) !important;
  box-shadow: 0 0 8px var(--bh-glow) !important;
}
.btr-thumb-popup input[type="range"]::-moz-range-track,
.btr-body-popup input[type="range"]::-moz-range-track { background: transparent !important; height: 6px; border: none !important; }
.btr-thumb-popup input[type="range"]::-moz-range-thumb,
.btr-body-popup input[type="range"]::-moz-range-thumb {
  width: 12px; height: 12px;
  border-radius: 50%;
  background: var(--bh-accent) !important;
  border: 2px solid var(--bh-bg-2) !important;
}

/* the darkest text colors Roblox uses: raise them at the source */
:root, html, body {
  --color-content-action-emphasis: #ffffff !important;
  --color-content-disabled: #8a98c2 !important;
  --color-content-system-contrast: #ffffff !important;
  --color-extended-gray-600: #9aa8d4 !important;
  --color-extended-gray-700: #aab6dc !important;
}

/* ==========================================================
   36. BROAD NET FOR REMAINING DARK TEXT + BLACK ICONS
   ========================================================== */

/* whole gray scale Roblox uses for text, raised to light tones */
:root, html, body {
  --color-extended-gray-400: #7f8db8 !important;
  --color-extended-gray-500: #8a98c2 !important;
  --color-extended-gray-600: #9aa8d4 !important;
  --color-extended-gray-700: #aab6dc !important;
  --color-extended-gray-800: #c3cdee !important;
  --color-extended-gray-900: #d6def5 !important;
  --color-content-muted: #b4c0e6 !important;
  --color-content-default: #d6def5 !important;
  --color-content-emphasis: #eef2ff !important;
}

/* text colored through Tailwind arbitrary values: [color:var(--color-extended-gray-...)] */
[class*="color:var(--color-extended-gray"],
[class*="color:var(--color-content"],
[class*="text-gray"], [class*="content-gray"] {
  color: var(--bh-muted) !important;
  opacity: 1 !important;
}

/* inline SVG icons that default to black */
svg { color: #b4c0e6; }
svg:not([fill="none"]):not([class*="Mui"]) path:not([fill]) { fill: currentColor; }

/* old sprite icons: tint to light (statuses, logos, badges and Robux keep their own look) */
[class^="icon-"]:not([class*="online"]):not([class*="offline"]):not([class*="game"]):not([class*="verified"]):not([class*="badge"]):not([class*="premium"]):not([class*="blocked"]):not([class*="robux"]):not([class*="logo"]):not([class*="check-selection"]),
[class*=" icon-"]:not([class*="online"]):not([class*="offline"]):not([class*="game"]):not([class*="verified"]):not([class*="badge"]):not([class*="premium"]):not([class*="blocked"]):not([class*="robux"]):not([class*="logo"]):not([class*="check-selection"]) {
  filter: var(--bh-icon-tint);
}

/* text that is dimmed through opacity utilities on text elements */
.text-body-small, .text-body-medium, .text-body-large,
.text-title-small, .text-title-medium, .text-title-large,
.text-heading-small, .text-heading-medium, .text-heading-large,
.text-label-small, .text-label-medium, .text-label-large {
  opacity: 1 !important;
}

/* ==========================================================
   37. SOCIAL ICONS (white squares) + "Join" BUTTON LABELS
   ========================================================== */

/* section 36 tinted every sprite icon to flat white; social-media icons are
   full-color images on a square, so they turned into white boxes. Undo for them. */
[class*="icon-social"], [class*="social-icon"], .social-icon {
  filter: none !important;
  opacity: 1 !important;
}

/* any Foundation button except the transparent "link/ghost" kind: white label,
   whatever its own color class is (covers the dark-green "Join") */
.foundation-web-button:not(.bg-action-link):not(.bg-none) *,
a.foundation-web-button:not(.bg-action-link):not(.bg-none) * {
  color: #fff !important;
  opacity: 1 !important;
}
.foundation-web-button:not(.bg-action-link):not(.bg-none) {
  opacity: 1 !important;
}
.foundation-web-button:disabled * { opacity: .8 !important; }

/* ==========================================================
   38. COLORED SPRITE ICONS THAT MUST KEEP THEIR OWN COLORS
   (LIMITED / LIMITED U ribbons, membership badges, sale tags ...)
   section 36 flattened them to white; restore them
   ========================================================== */
[class*="icon-limited"], [class*="limited-"], [class*="-limited"],
[class*="icon-bc"], [class*="icon-obc"], [class*="icon-tbc"],
[class*="icon-sale"], [class*="icon-new"], [class*="icon-pending"],
[class*="icon-restricted"], [class*="icon-offsale"], [class*="icon-collectible"],
[class*="icon-unique"],
[class*="icon-verified"], [class*="icon-warning"], [class*="icon-alert"],
[class*="icon-error"], [class*="icon-success"], [class*="icon-star"],
[class*="icon-heart"], [class*="icon-fire"], [class*="icon-trending"] {
  filter: none !important;
  opacity: 1 !important;
}

/* ==========================================================
   39. VOTE / PLAYER-COUNT ICONS: light again
   (they also carry the class "info-label", which the broad "label"
   exception in section 38 caught by mistake - that exception is removed
   and these are re-asserted here)
   ========================================================== */
.icon-votes-gray, .icon-playing-counts-gray, .icon-votes, .icon-playing-counts,
.icon-like, .icon-dislike, .icon-thumbs-up, .icon-thumbs-down {
  filter: var(--bh-icon-tint) !important;
  opacity: .9 !important;
}
}
